// Flat ESLint config for the Bench UI: the TypeScript and React-hooks recommended rule sets, nothing else.
// Formatting is not linted here; `npm run typecheck` already owns type errors.
import js from "@eslint/js";
import globals from "globals";
import reactHooks from "eslint-plugin-react-hooks";
import tseslint from "typescript-eslint";

export default tseslint.config(
  // schema.d.ts is generated by `npm run gen:api`; src/smeltery/bench/web is vite build output.
  { ignores: ["node_modules/", "dist/", "playwright-report/", "test-results/", "src/api/schema.d.ts"] },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    files: ["**/*.{ts,tsx}"],
    languageOptions: { globals: { ...globals.browser } },
    plugins: { "react-hooks": reactHooks },
    // Only the two classic hooks rules. plugin v7's `recommended` also turns on the React Compiler rules
    // (refs, purity, set-state-in-effect): they flag 31 existing sites, so adopting them is its own change.
    rules: {
      "react-hooks/rules-of-hooks": "error",
      "react-hooks/exhaustive-deps": "error",
    },
  },
  {
    // Node-side files: vite/playwright config, the gen:api script, and the e2e specs.
    files: ["*.config.{js,ts}", "scripts/**", "e2e/**"],
    languageOptions: { globals: { ...globals.node } },
  },
);
